// ============================================================
// STEP 1: Input validation & normalisation
// n8n Code node  |  Mode: "Run Once for All Items"
// Place directly after the Webhook node.
// ============================================================

const CONFIG = {
  GTIN_REQUIRED: false,            // true = missing GTIN becomes an error instead of a warning
  MAX_DAYS_IN_STOCK_WARN: 730,     // warn when stock is older than ~2 years
  COMPETITOR_OUTLIER_LOW: 0.5,     // competitor < 50% of our price  -> warning
  COMPETITOR_OUTLIER_HIGH: 2.0,    // competitor > 200% of our price -> warning
};

// ---------- 1. Unwrap webhook body (array or single object) ----------
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.body !== undefined && j.body !== null && typeof j.body === 'object') {
    rows.push(...(Array.isArray(j.body) ? j.body : [j.body]));
  } else {
    rows.push(j);
  }
}

// ---------- 2. Helpers ----------
const toNum = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  if (typeof v === 'string' && v.trim() !== '') return Number(v.trim().replace(',', '.'));
  return NaN;
};
const orNull = (n) => (Number.isNaN(n) ? null : n);
const median = (arr) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round(((s[m - 1] + s[m]) / 2) * 100) / 100;
};

// GS1 check-digit validation (GTIN-8, 12, 13, 14)
const gtinValid = (g) => {
  if (!/^(\d{8}|\d{12,14})$/.test(g)) return false;
  const d = g.split('').map(Number);
  const check = d.pop();
  let sum = 0;
  d.reverse().forEach((n, i) => { sum += n * (i % 2 === 0 ? 3 : 1); });
  return (10 - (sum % 10)) % 10 === check;
};

// ---------- 3. Validate each row ----------
const seenSkus = new Set();

const results = rows.map((row, idx) => {
  row = row && typeof row === 'object' ? row : {};
  const errors = [];
  const warnings = [];

  const str = (k) => (row[k] === undefined || row[k] === null ? '' : String(row[k]).trim());

  // --- text fields ---
  const sku = str('sku');
  const productName = str('product_name');
  const department = str('department');
  const category = str('category');
  const gtin = str('gtin');

  if (!sku) errors.push('Missing sku');
  if (!productName) errors.push('Missing product_name');
  if (!department) errors.push('Missing department');
  if (!category) errors.push('Missing category');

  if (sku) {
    if (seenSkus.has(sku)) errors.push(`Duplicate sku: ${sku}`);
    seenSkus.add(sku);
  }

  if (!gtin) {
    (CONFIG.GTIN_REQUIRED ? errors : warnings).push('Missing GTIN');
  } else if (!gtinValid(gtin)) {
    errors.push(`Invalid GTIN (format or GS1 check digit): ${gtin}`);
  }

  // --- numeric fields ---
  const cost = toNum(row.cost_price_sek);
  const price = toNum(row.current_price_sek);
  const daysInStock = toNum(row.days_in_stock);
  const units = toNum(row.units_in_stock);
  const velocity = toNum(row.sales_velocity_30d);
  const sinceChange = row.days_since_last_price_change === undefined
    ? NaN : toNum(row.days_since_last_price_change);

  if (!(cost > 0)) errors.push('cost_price_sek must be a number > 0');
  if (!(price > 0)) errors.push('current_price_sek must be a number > 0');
  if (!(daysInStock >= 0)) errors.push('days_in_stock must be a number >= 0');
  if (!(units >= 0) || !Number.isInteger(units)) errors.push('units_in_stock must be a whole number >= 0');
  if (!(velocity >= 0)) errors.push('sales_velocity_30d must be a number >= 0');
  if (row.days_since_last_price_change !== undefined && !(sinceChange >= 0)) {
    errors.push('days_since_last_price_change must be a number >= 0');
  }

  // --- competitor prices (new array field, legacy single field still accepted) ---
  let rawComps = row.competitor_prices_sek;
  if (rawComps === undefined && row.competitor_price_sek !== undefined) rawComps = [row.competitor_price_sek];
  if (rawComps === undefined || rawComps === null) rawComps = [];

  let comps = [];
  if (!Array.isArray(rawComps)) {
    errors.push('competitor_prices_sek must be an array of numbers');
  } else {
    comps = rawComps.map(toNum);
    if (comps.some((c) => !(c > 0))) {
      errors.push('competitor_prices_sek contains a non-numeric or non-positive value');
      comps = comps.filter((c) => c > 0);
    }
  }

  // --- business-sanity warnings (row still passes) ---
  if (price > 0 && cost > 0 && price < cost) {
    warnings.push('Current price is below cost (negative margin)');
  }
  if (!comps.length && !errors.some((e) => e.startsWith('competitor_prices_sek'))) {
    warnings.push('No competitor prices available: competitor-based pricing skipped');
  }
  if (price > 0 && comps.some((c) => c < price * CONFIG.COMPETITOR_OUTLIER_LOW || c > price * CONFIG.COMPETITOR_OUTLIER_HIGH)) {
    warnings.push('Competitor price looks like an outlier compared with our price');
  }
  if (daysInStock > CONFIG.MAX_DAYS_IN_STOCK_WARN) {
    warnings.push(`days_in_stock above ${CONFIG.MAX_DAYS_IN_STOCK_WARN}`);
  }

  // ---------- 4. Build normalised output ----------
  const compMin = comps.length ? Math.min(...comps) : null;
  const valid = errors.length === 0;

  const out = {
    row_number: idx + 1,
    validation_status: valid ? 'valid' : 'rejected',
    validation_errors: errors,
    validation_warnings: warnings,

    sku,
    gtin: gtin || null,
    product_name: productName,
    brand: str('brand') || null,
    department,
    category,
    subcategory: str('subcategory') || null,
    supplier: str('supplier') || null,
    store: str('store') || null,
    variant: str('variant') || null,

    cost_price_sek: orNull(cost),
    current_price_sek: orNull(price),
    days_in_stock: orNull(daysInStock),
    units_in_stock: orNull(units),
    sales_velocity_30d: orNull(velocity),
    days_since_last_price_change: orNull(sinceChange),

    competitor_prices_sek: comps,
    competitor_count: comps.length,
    competitor_min_sek: compMin,
    competitor_median_sek: median(comps),
    competitor_max_sek: comps.length ? Math.max(...comps) : null,

    // Backward compatibility: the current pricing node still reads this single field.
    // When no competitor data exists, fall back to our own price so the price is held.
    competitor_price_sek: compMin !== null ? compMin : orNull(price),
  };

  if (!valid) out.raw_input = row;   // keep original data for review

  return { json: out };
});

return results;

// ============================================================
// STEP 2: Pricing engine v2
// n8n Code node (replaces "Code in JavaScript")  |  Mode: "Run Once for All Items"
// Input : valid rows from "Valid rows?" (output of Step 1)
// Output: ONE item with the per-SKU decisions, the report table,
//         the capital estimate, the chart link and a facts block for the LLM.
// ============================================================

const CONFIG = {
  // Minimum markup over cost, by department (price floor = cost x (1 + markup))
  MIN_MARKUP_BY_DEPARTMENT: { Electronics: 0.10, Furniture: 0.25, Outdoor: 0.20, Home: 0.20, Sports: 0.20 },
  DEFAULT_MIN_MARKUP: 0.15,

  COMPETITOR_UNDERCUT: 0.02,          // undercut the cheapest credible competitor by 2%
  COMPETITOR_OUTLIER_LOW: 0.5,        // competitor prices below 50% of our price are ignored as outliers

  MAX_MARKDOWN_PER_RUN: 0.25,         // no price falls more than 25% in one run
  MAX_STOCK_PRESSURE_DEPTH: 0.30,     // age + cover markdown depth is capped at 30%
  MIN_MARKDOWN_PCT_TO_ACT: 1,         // ignore changes smaller than 1%
  PRICE_CHANGE_COOLDOWN_DAYS: 14,     // do not touch a price changed less than 14 days ago

  FAST_MOVER_MAX_COVER_WEEKS: 8,      // fast mover = <= 8 weeks of cover ...
  FAST_MOVER_MAX_AGE_DAYS: 60,        // ... and <= 60 days in stock

  CLEARANCE_MIN_AGE_DAYS: 120,        // clearance = >= 120 days in stock ...
  CLEARANCE_MIN_COVER_WEEKS: 26,      // ... and >= 26 weeks of cover

  APPROVAL_THRESHOLD_PCT: 15,         // markdowns >= 15% are flagged for human approval

  // Markdown depth by days in stock
  AGE_TIERS: [
    { max: 30, depth: 0 }, { max: 60, depth: 0.03 }, { max: 90, depth: 0.08 },
    { max: 120, depth: 0.15 }, { max: Infinity, depth: 0.25 },
  ],
  // Markdown depth by weeks of cover (stock on hand / weekly sales rate)
  COVER_TIERS: [
    { max: 8, depth: 0 }, { max: 13, depth: 0.03 }, { max: 26, depth: 0.06 },
    { max: 52, depth: 0.12 }, { max: Infinity, depth: 0.20 },
  ],
};

// ---------- helpers ----------
const items = $input.all().map((i) => i.json);
const round2 = (n) => Math.round(n * 100) / 100;
const pct1 = (n) => Math.round(n * 10) / 10;
const tier = (tiers, v) => tiers.find((t) => v <= t.max).depth;
const roundUp9 = (x) => Math.ceil((x + 1) / 10) * 10 - 1;   // next price ending in 9 (never below x)
const sek = (n) => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const clean = (s) => String(s).replace(/\|/g, '/');

// ---------- decision per SKU ----------
const results = items.map((d) => {
  const price = d.current_price_sek;
  const cost = d.cost_price_sek;
  const units = d.units_in_stock ?? 0;
  const velocity = d.sales_velocity_30d ?? 0;
  const days = d.days_in_stock ?? 0;
  const since = d.days_since_last_price_change;

  const markup = CONFIG.MIN_MARKUP_BY_DEPARTMENT[d.department] ?? CONFIG.DEFAULT_MIN_MARKUP;
  const floor = round2(cost * (1 + markup));

  const weeklyRate = (velocity * 7) / 30;
  const cover = weeklyRate > 0 ? Math.min(units / weeklyRate, 999) : (units > 0 ? 999 : 0);

  const comps = Array.isArray(d.competitor_prices_sek) && d.competitor_prices_sek.length
    ? d.competitor_prices_sek
    : (d.competitor_price_sek ? [d.competitor_price_sek] : []);
  const credible = comps.filter((c) => c >= price * CONFIG.COMPETITOR_OUTLIER_LOW);
  const compRef = credible.length ? Math.min(...credible) : null;

  let action = 'HOLD';
  let rec = price;
  const reasons = [];
  let ageDepth = 0, coverDepth = 0, depth = 0;

  if (units === 0) {
    reasons.push('No stock on hand');
  } else if (price < floor) {
    action = 'REVIEW';
    reasons.push(`Current price is below the margin floor (${sek(floor)} SEK)`);
  } else if (since !== null && since !== undefined && since < CONFIG.PRICE_CHANGE_COOLDOWN_DAYS) {
    reasons.push(`Price changed ${since} days ago (cooldown ${CONFIG.PRICE_CHANGE_COOLDOWN_DAYS} days)`);
  } else if (cover <= CONFIG.FAST_MOVER_MAX_COVER_WEEKS && days <= CONFIG.FAST_MOVER_MAX_AGE_DAYS) {
    reasons.push(`Fast mover: ${cover.toFixed(1)} weeks of cover, ${days} days in stock`);
  } else {
    ageDepth = tier(CONFIG.AGE_TIERS, days);
    coverDepth = tier(CONFIG.COVER_TIERS, cover);
    depth = Math.min(ageDepth + coverDepth, CONFIG.MAX_STOCK_PRESSURE_DEPTH);

    const stockPrice = price * (1 - depth);
    const compPrice = compRef !== null && compRef < price ? compRef * (1 - CONFIG.COMPETITOR_UNDERCUT) : price;
    const raw = Math.min(stockPrice, compPrice);
    const capPrice = price * (1 - CONFIG.MAX_MARKDOWN_PER_RUN);

    const target = Math.max(raw, capPrice, floor);
    rec = Math.min(roundUp9(target), price);
    let md = ((price - rec) / price) * 100;

    if (md < CONFIG.MIN_MARKDOWN_PCT_TO_ACT) {
      rec = price;
      reasons.push('Calculated change below the minimum step: price held');
    } else {
      if (compPrice < price) reasons.push(`Cheapest credible competitor ${sek(compRef)} SEK`);
      if (depth > 0) reasons.push(`Stock pressure ${pct1(depth * 100)}% (${days} days in stock, ${cover >= 999 ? 'no recent sales' : cover.toFixed(1) + ' weeks of cover'})`);
      if (capPrice > raw && capPrice >= floor) reasons.push(`Capped at ${CONFIG.MAX_MARKDOWN_PER_RUN * 100}% max markdown per run`);
      if (floor > raw && floor >= capPrice) reasons.push(`Limited by margin floor (${sek(floor)} SEK)`);
      const clearance = days >= CONFIG.CLEARANCE_MIN_AGE_DAYS && cover >= CONFIG.CLEARANCE_MIN_COVER_WEEKS;
      action = clearance ? 'CLEARANCE' : 'MARKDOWN';
    }
  }

  const markdownPct = ((price - rec) / price) * 100;
  const marginPct = ((rec - cost) / rec) * 100;

  return {
    sku: d.sku, gtin: d.gtin, product_name: d.product_name, department: d.department, category: d.category,
    action,
    current_price_sek: price,
    recommended_price_sek: rec,
    markdown_percent: pct1(markdownPct),
    profit_margin_percent: pct1(marginPct),
    cost_price_sek: cost,
    margin_floor_sek: floor,
    units_in_stock: units,
    days_in_stock: days,
    weeks_of_cover: cover >= 999 ? null : pct1(cover),
    age_depth_pct: pct1(ageDepth * 100),
    cover_depth_pct: pct1(coverDepth * 100),
    approval_required: markdownPct >= CONFIG.APPROVAL_THRESHOLD_PCT,
    reasons,
  };
});

// ---------- aggregates (all deterministic) ----------
const changed = results.filter((r) => r.action === 'MARKDOWN' || r.action === 'CLEARANCE');
const count = (a) => results.filter((r) => r.action === a).length;
const sum = (arr, f) => arr.reduce((s, r) => s + f(r), 0);

const capitalTiedAtCost = sum(changed, (r) => r.units_in_stock * r.cost_price_sek);
const recoverable = sum(changed, (r) => r.units_in_stock * r.recommended_price_sek);
const revenueGivenUp = sum(changed, (r) => r.units_in_stock * (r.current_price_sek - r.recommended_price_sek));
const marginAtRecommended = sum(changed, (r) => r.units_in_stock * (r.recommended_price_sek - r.cost_price_sek));
const avgMarkdown = changed.length ? sum(changed, (r) => r.markdown_percent) / changed.length : 0;
const top = [...changed].sort((a, b) => b.markdown_percent - a.markdown_percent).slice(0, 3);
const approvals = results.filter((r) => r.approval_required).map((r) => r.sku);
const reviews = results.filter((r) => r.action === 'REVIEW');
const fastMovers = results.filter((r) => r.reasons.some((x) => x.startsWith('Fast mover'))).map((r) => r.sku);

// ---------- facts block for the LLM ----------
const facts = [
  'RUN FACTS (all amounts in SEK):',
  `- SKUs analysed: ${results.length}`,
  `- Actions: ${count('HOLD')} HOLD, ${count('MARKDOWN')} MARKDOWN, ${count('CLEARANCE')} CLEARANCE, ${count('REVIEW')} REVIEW`,
  ...top.map((r, i) => `- Markdown #${i + 1}: ${r.sku} ${r.product_name}, ${r.markdown_percent}% (${sek(r.current_price_sek)} to ${sek(r.recommended_price_sek)})`),
  `- Average markdown across marked-down SKUs: ${pct1(avgMarkdown)}%`,
  `- Capital tied up at cost in marked-down stock: ${sek(capitalTiedAtCost)}`,
  `- Total Capital Recoverable Estimate (cash if that stock sells at recommended prices): ${sek(recoverable)}`,
  `- Revenue given up versus current prices: ${sek(revenueGivenUp)}`,
  `- SKUs with a price change: ${changed.length}`,
  `- Number of SKUs needing approval (markdown of ${CONFIG.APPROVAL_THRESHOLD_PCT}% or more): ${approvals.length}${approvals.length ? ' (' + approvals.join(', ') + ')' : ''}`,
  `- SKUs flagged for review: ${reviews.length ? reviews.map((r) => `${r.sku} (${r.reasons[0]})`).join('; ') : 'none'}`,
  `- Fast movers held at current price: ${fastMovers.length ? fastMovers.join(', ') : 'none'}`,
  `- Maximum markdown allowed in one run: ${CONFIG.MAX_MARKDOWN_PER_RUN * 100}%`,
].join('\n');

// ---------- structured facts + deterministic fallback summary (used by the summary guard) ----------
const factsObj = {
  skus: results.length,
  hold: count('HOLD'),
  markdown: count('MARKDOWN'),
  clearance: count('CLEARANCE'),
  review: count('REVIEW'),
  changed_count: changed.length,
  avg_markdown_pct: pct1(avgMarkdown),
  top_markdown_pcts: top.map((r) => r.markdown_percent),
  capital_tied: Math.round(capitalTiedAtCost),
  recoverable: Math.round(recoverable),
  revenue_given_up: Math.round(revenueGivenUp),
  approvals_count: approvals.length,
  approval_threshold_pct: CONFIG.APPROVAL_THRESHOLD_PCT,
  max_markdown_pct: CONFIG.MAX_MARKDOWN_PER_RUN * 100,
};

const topLine = top.length
  ? ` The largest markdown is ${top[0].markdown_percent}% on ${top[0].sku} (${top[0].product_name}).`
  : '';
const fallbackSummary =
  `This run analysed ${results.length} SKUs: ${count('HOLD')} held at the current price, ${count('MARKDOWN')} marked down and ${count('CLEARANCE')} on clearance.` +
  (changed.length
    ? ` The average markdown across the ${changed.length} SKUs with a price change is ${pct1(avgMarkdown)}%.${topLine}`
    : ' No SKU received a price change.') +
  ` Capital tied up at cost in these SKUs is ${sek(capitalTiedAtCost)} SEK, and the Total Capital Recoverable Estimate is ${sek(recoverable)} SEK if they sell at the recommended prices, with ${sek(revenueGivenUp)} SEK of revenue given up versus current prices.` +
  ` ${approvals.length} SKUs need approval and ${reviews.length} SKUs are flagged for review.`;

// ---------- Markdown: pricing action table ----------
const sorted = [...results].sort((a, b) => b.markdown_percent - a.markdown_percent || a.sku.localeCompare(b.sku));
const tableRows = sorted.map((r) =>
  `| ${r.sku} | ${clean(r.product_name)} | ${r.action}${r.approval_required ? ' ⚠️' : ''} | ${sek(r.current_price_sek)} | ${sek(r.recommended_price_sek)} | ${r.markdown_percent}% | ${r.profit_margin_percent}% | ${r.weeks_of_cover === null ? 'no sales' : r.weeks_of_cover} | ${r.days_in_stock} | ${clean(r.reasons.join('; '))} |`
);
const pricingTable = [
  '| SKU | Product | Action | Current (SEK) | Recommended (SEK) | Markdown | Margin | Cover (weeks) | Days in stock | Why |',
  '| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | --- |',
  ...tableRows,
  '',
  `⚠️ = markdown of ${CONFIG.APPROVAL_THRESHOLD_PCT}% or more, recommended for human approval before the price is changed.`,
].join('\n');

// ---------- Markdown: capital section ----------
const capitalSection = [
  `**Total Capital Recoverable Estimate: ${sek(recoverable)} SEK**`,
  '',
  `Cash recovered if all stock in the ${changed.length} marked-down SKUs sells at the recommended prices.`,
  '',
  '| Metric | SEK |',
  '| --- | ---: |',
  `| Capital tied up at cost (marked-down SKUs) | ${sek(capitalTiedAtCost)} |`,
  `| Cash recoverable at recommended prices | ${sek(recoverable)} |`,
  `| Margin earned at recommended prices | ${sek(marginAtRecommended)} |`,
  `| Revenue given up versus current prices | ${sek(revenueGivenUp)} |`,
  '',
  '_Assumes all units sell; it is not time-adjusted for sales velocity._',
].join('\n');

// ---------- chart ----------
const chartConfig = {
  type: 'bar',
  data: {
    labels: results.map((r) => r.sku),
    datasets: [
      { label: 'Current Price (SEK)', data: results.map((r) => r.current_price_sek) },
      { label: 'Recommended Price (SEK)', data: results.map((r) => r.recommended_price_sek) },
    ],
  },
};
const base64Config = Buffer.from(JSON.stringify(chartConfig)).toString('base64');
const chartImage = `![Pricing Chart](https://quickchart.io/chart?w=900&h=400&encoding=base64&c=${base64Config})`;

return [{
  json: {
    facts_for_llm: facts,
    facts: factsObj,
    fallback_summary: fallbackSummary,
    pricing_table_md: pricingTable,
    capital_section_md: capitalSection,
    chart_image: chartImage,
    results,
    summary: {
      skus: results.length, hold: count('HOLD'), markdown: count('MARKDOWN'),
      clearance: count('CLEARANCE'), review: count('REVIEW'),
      capital_tied_at_cost: capitalTiedAtCost, recoverable, revenue_given_up: revenueGivenUp,
    },
  },
}];

// ============================================================
// STEP 3: Report assembly with SUMMARY GUARD (deterministic summary + optional verified AI commentary)
// n8n Code node (replaces "Code in JavaScript1")  |  Mode: "Run Once for All Items"
// Sits between "Basic LLM Chain" and "Create a file".
// Node names used below must match your canvas:
//   "Pricing_Engine_JS"    = pricing engine
//   "Validate & Normalise" = validation node
// ============================================================

const GUARD = {
  CLAIM_LEVEL_CHECK: true,   // false = only check that numbers exist in the facts (weaker)
  PCT_TOLERANCE: 0.05,       // percentages must match within 0.05
  MONEY_TOLERANCE: 0.5,      // SEK amounts are whole numbers
};

const engine = $('Pricing_Engine_JS').first().json;
const F = engine.facts;
const results = engine.results;
if (!F || !results || !engine.fallback_summary || !engine.facts_for_llm) {
  throw new Error("The 'Pricing_Engine_JS' output is missing 'facts' / 'fallback_summary'. It is running an older pricing engine: paste the latest pricing_engine.js into that node, then run the workflow again.");
}
const validated = $('Validate & Normalise').all().map((i) => i.json);
let policy = null;   // optional: present once the policy RAG nodes are in the workflow
try { policy = $('Policy_Collect_JS').first().json; } catch (e) { policy = null; }

const llmText = (($input.first().json.text) || '')
  .replace(/^#+.*$/gm, '')   // drop any headings the model adds
  .trim();

// ------------------------------------------------------------
// SUMMARY GUARD
// Tier 0: every SKU code mentioned must exist, and a percentage
//         written next to a SKU must be that SKU's own markdown.
// Tier 1: every number in the text must appear in the facts block.
// Tier 2: every number must match the fact its own clause is about
//         (average, recoverable, tied-up capital, counts, ...).
// ------------------------------------------------------------
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const productNames = results.map((r) => r.product_name).sort((a, b) => b.length - a.length);
const skuDigits = new Set(results.map((r) => r.sku.replace(/\D/g, '')));
const normSku = (x) => 'SKU-' + String(x).replace(/\D/g, '');

// Remove SKU codes and product names so digits inside them ("64GB", "SKU-4089") are not read as claims
const scrub = (s) => {
  let t = s;
  for (const n of productNames) t = t.replace(new RegExp(esc(n), 'gi'), ' PRODUCT ');
  t = t.replace(/SKU[\s-]?\d+/gi, ' SKU ');
  // bare known SKU numbers such as "SKUs 9912, 1060 and 4089" (not prices: no comma/decimal/percent/SEK around them)
  return t.replace(/(?<![\d,.])(\d{3,6})(?!\d|,\d|%|\.\d|\s*SEK)/g, (m, d) => (skuDigits.has(d) ? ' SKU ' : m));
};

const WORDS = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
  eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19, twenty: 20 };
const numberWordsToDigits = (s) => s.replace(
  /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)\b(?=\s+(?:\w+\s+){0,2}(?:SKUs?|items?|products?)\b|\s+of\s+(?:the\s+|all\s+)?\d+\s+SKUs?\b)/gi,
  (w) => String(WORDS[w.toLowerCase()])
);

const numbers = (s) => {
  const out = [];
  const re = /(\d{1,3}(?:,\d{3})+|\d+)(\.\d+)?\s*(%)?/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    out.push({
      value: parseFloat(m[1].replace(/,/g, '') + (m[2] || '')),
      pct: Boolean(m[3]),
      raw: m[0].trim(),
      start: m.index,
      end: re.lastIndex,
    });
  }
  return out;
};

const near = (a, b, tol) => Math.abs(a - b) <= tol;
const inList = (v, list, tol) => list.some((x) => x !== undefined && x !== null && near(v, x, tol));

// What each clause is about, in priority order (first match wins)
const LABELS = [
  { name: 'average markdown', re: /\b(averag(?:e|es|ed|ing)|mean)\b/i,
    pct: [F.avg_markdown_pct], count: [F.changed_count, F.skus, F.markdown, F.clearance] },
  { name: 'recoverable capital', re: /\brecover(?:able|ed|y)?\b/i, money: [F.recoverable] },
  { name: 'capital tied up', re: /\btied\b|\bat cost\b/i, money: [F.capital_tied] },
  { name: 'revenue given up', re: /\b(given up|forgone|foregone|forfeit(?:ed)?|lost revenue|revenue lost)\b/i, money: [F.revenue_given_up] },
  { name: 'markdown cap', re: /\b(allowed|permitted|capped?|capping|limit(?:ed|s)?|ceiling|per run|in one run|single run)\b/i, pct: [F.max_markdown_pct] },
  { name: 'largest markdown', re: /\b(largest|highest|biggest|deepest|steepest|maximum)\b/i, pct: [F.top_markdown_pcts[0]] },
  { name: 'SKUs analysed', re: /\b(analy[sz]ed|processed|assessed|covered)\b/i, count: [F.skus] },
  { name: 'SKUs with a price change', re: /\b(adjust(?:ed|ment|ments)?|repric(?:ed|ing)|re-priced|price changes?|price cuts?|reductions?|reduced|changed)\b/i, count: [F.changed_count] },
  { name: 'clearance count', re: /\bclearance\b/i, count: [F.clearance] },
  { name: 'held count', re: /\b(held|hold|holds|unchanged)\b/i, count: [F.hold] },
  { name: 'review count', re: /\breview\b/i, count: [F.review] },
  { name: 'approval', re: /\bapprov(?:al|ed|e)\b/i, count: [F.approvals_count], pct: [F.approval_threshold_pct] },
  { name: 'markdowns', generic: true, re: /\b(markdowns?|marked[- ]down)\b/i,
    count: [F.markdown, F.clearance, F.changed_count],
    pct: [...F.top_markdown_pcts, F.avg_markdown_pct, F.approval_threshold_pct, F.max_markdown_pct] },
];

function verifySummary(text) {
  const problems = [];
  if (!text) return ['Empty LLM summary'];

  // ---- Tier 0: SKU mentions ----
  const bySku = Object.fromEntries(results.map((r) => [r.sku, r]));
  for (const m of text.matchAll(/SKU[\s-]?\d+/gi)) {
    if (!bySku[normSku(m[0])]) problems.push(`Unknown SKU mentioned: ${m[0]}`);
  }
  const skuPct = [
    /(SKU[\s-]?\d+)(?:(?!SKU)[^.%]){0,60}?(\d+(?:\.\d+)?)\s*%/gi,                     // "SKU-1060 ... 24.9%"
    /(\d+(?:\.\d+)?)\s*%\s+(?:markdown\s+)?(?:on|for)\s+(?:the\s+)?(SKU[\s-]?\d+)/gi,   // "24.9% on SKU-1060"
  ];
  skuPct.forEach((re, i) => {
    for (const m of text.matchAll(re)) {
      const sku = normSku(i === 0 ? m[1] : m[2]);
      const pct = parseFloat(i === 0 ? m[2] : m[1]);
      const r = bySku[sku];
      const ctx = m[0] + text.slice(m.index + m[0].length, m.index + m[0].length + 30);
      const isRule = (near(pct, F.approval_threshold_pct, GUARD.PCT_TOLERANCE) || near(pct, F.max_markdown_pct, GUARD.PCT_TOLERANCE))
        && /(or more|or higher|or above|and above|threshold|cap|maximum|limit|exceed|above|over|at least|allowed|approval)/i.test(ctx);
      if (r && !isRule && !near(pct, r.markdown_percent, GUARD.PCT_TOLERANCE)) {
        problems.push(`${sku}: text says ${pct}% but the verified markdown is ${r.markdown_percent}%`);
      }
    }
  });

  // ---- Tier 0b: SKUs listed next to "approval" must all be flagged for approval ----
  const skusIn = (str) => {
    const set = new Set();
    for (const m of str.matchAll(/SKU[\s-]?\d+/gi)) set.add(normSku(m[0]));
    for (const m of str.matchAll(/(?<![\d,.])(\d{3,6})(?!\d|,\d|%|\.\d|\s*SEK)/g)) {
      if (skuDigits.has(m[1])) set.add(normSku(m[1]));
    }
    return set;
  };
  for (const sent of text.split(/(?<=[.!?])\s+/)) {
    if (!/\bapprov/i.test(sent)) continue;
    if (/\b(no|not|none|without|never|doesn't|don't|isn't|aren't)\b/i.test(sent)) continue;   // negated: skip
    for (const sku of skusIn(sent)) {
      const r = bySku[sku];
      if (r && !r.approval_required) {
        problems.push(`${sku} is listed as needing approval, but its markdown is ${r.markdown_percent}%, below the ${F.approval_threshold_pct}% threshold`);
      }
    }
  }

  // ---- Tier 1: every number must exist in the facts ----
  const scrubbed = numberWordsToDigits(scrub(text));
  const allowed = numbers(scrub(engine.facts_for_llm)).map((n) => n.value);
  for (const n of numbers(scrubbed)) {
    if (!inList(n.value, allowed, GUARD.PCT_TOLERANCE)) {
      problems.push(`Number not in the verified facts: ${n.raw}`);
    }
  }

  // ---- Tier 2: every number must match the topic word nearest to it ----
  if (GUARD.CLAIM_LEVEL_CHECK) {
    const matchesOf = (re, str) => {
      const g = new RegExp(re.source, 'gi');
      const out = [];
      let m;
      while ((m = g.exec(str)) !== null) out.push({ start: m.index, end: m.index + m[0].length });
      return out;
    };
    const gapTo = (n, ms) => Math.min(...ms.map((m) => (n.start >= m.end ? n.start - m.end : m.start >= n.end ? m.start - n.end : 0)));

    const clauses = scrubbed.split(/(?<=[.!?])\s+|;\s*|:\s+|,\s+|\s+(?:and|but|while|whereas)\s+/i).filter(Boolean);
    for (const clause of clauses) {
      const hits = LABELS.map((l, order) => ({ l, order, ms: matchesOf(l.re, clause) })).filter((h) => h.ms.length);
      if (!hits.length) continue;
      const toks = numbers(clause);

      for (const n of toks) {
        const isMoney = !n.pct && (n.value >= 1000 || /^\s*SEK/i.test(clause.slice(n.end, n.end + 6)));
        const kind = n.pct ? 'pct' : isMoney ? 'money' : 'count';
        let cands = hits.filter((h) => h.l[kind]).map((h) => ({ ...h, gap: gapTo(n, h.ms) }));
        if (!cands.length) continue;
        // For percentages a specific topic (average, largest, approval) beats the generic "markdown" word
        if (kind === 'pct' && cands.some((c) => !c.l.generic)) cands = cands.filter((c) => !c.l.generic);
        cands.sort((x, y) => x.gap - y.gap || x.order - y.order);
        // a percentage equal to the per-run cap, in a clause that talks about a cap or limit, is the cap ("capped at the 25% maximum")
        const capCand = cands.find((c) => c.l.name === 'markdown cap');
        const pick = kind === 'pct' && capCand && near(n.value, F.max_markdown_pct, GUARD.PCT_TOLERANCE) ? capCand : cands[0];
        if (kind === 'count' && /\b(top|first|largest|biggest|deepest|highest)\s+(?:the\s+)?$/i.test(clause.slice(0, n.start))) continue;
        let expected = pick.l[kind];

        if ((pick.l.name === 'markdowns' || pick.l.name === 'SKUs with a price change') && kind === 'count') {
          // "9 SKUs required a markdown of 15% or more": a count next to the approval threshold is the approval count
          const hasThreshold = pick.l.name === 'markdowns' && toks.some((o) => o.pct && near(o.value, F.approval_threshold_pct, GUARD.PCT_TOLERANCE));
          if (hasThreshold) {
            expected = [F.approvals_count];
          } else if (/\b(of|across|among|out of|from|in|over|covering)\s+(?:the\s+|all\s+)?$/i.test(clause.slice(0, n.start))
            && /^\s*SKUs?\b/i.test(clause.slice(n.end))
            && toks.some((o) => o !== n && !o.pct && o.value < 1000 && inList(o.value, expected, 0.001))) {
            // "analysis of 15 SKUs resulted in 10 markdowns": a total SKU count is fine as the population
            expected = [...expected, F.skus];
          }
        }

        const tol = kind === 'pct' ? GUARD.PCT_TOLERANCE : kind === 'money' ? GUARD.MONEY_TOLERANCE : 0.001;
        if (!inList(n.value, expected, tol)) {
          const verified = expected.filter((x) => x !== undefined).join(' or ');
          problems.push(`Claim mismatch (${pick.l.name}): "${clause.trim()}": ${n.raw} but the verified value is ${verified}`);
        }
      }
    }
  }
  return problems;
}

const problems = verifySummary(llmText);
const useLlm = problems.length === 0;
const narrative = engine.fallback_summary;   // the Executive Summary is always the deterministic one

// ------------------------------------------------------------
// Data quality section
// ------------------------------------------------------------
const rejected = validated.filter((v) => v.validation_status === 'rejected');
const warned = validated.filter((v) => v.validation_status === 'valid' && v.validation_warnings.length);
const label = (v) => v.sku || `row ${v.row_number}`;

const dq = [
  `Rows received: ${validated.length} | Accepted: ${validated.length - rejected.length} | Rejected: ${rejected.length} | Accepted with warnings: ${warned.length}`,
];
if (rejected.length) {
  dq.push('', '**Rejected rows (not priced):**', ...rejected.map((v) => `- ${label(v)}: ${v.validation_errors.join('; ')}`));
}
if (warned.length) {
  dq.push('', '**Warnings (priced, please check):**', ...warned.map((v) => `- ${label(v)}: ${v.validation_warnings.join('; ')}`));
}
dq.push('', useLlm
  ? '**AI commentary:** included. It was written by the local LLM and verified against the calculated figures.'
  : `**AI commentary:** omitted. The LLM text failed verification (${problems.length} problem${problems.length === 1 ? '' : 's'}); the Executive Summary above is unaffected.`);
if (!useLlm) dq.push(...problems.map((p) => `- ${p}`));

// ------------------------------------------------------------
// Final report
// ------------------------------------------------------------
const report = [
  '# Retail Markdown Strategy Report',
  `_Generated ${$now.toFormat('yyyy-MM-dd HH:mm')} | All amounts in SEK_`,
  '',
  '## Executive Summary',
  '',
  narrative,
  '',
  ...(useLlm ? [
    '## AI Commentary',
    '',
    llmText,
    '',
    '_Optional commentary from a local LLM, checked against the calculated figures. The Executive Summary above is the authoritative version._',
    '',
  ] : []),
  '## Pricing Action Table',
  '',
  engine.pricing_table_md,
  '',
  '## Total Capital Recoverable Estimate',
  '',
  engine.capital_section_md,
  '',
  ...(policy && policy.policy_section_md ? ['## Policy Review', '', policy.policy_section_md, ''] : []),
  '## Data Quality',
  '',
  dq.join('\n'),
  '',
  '## Visual Chart',
  '',
  engine.chart_image,
  '',
].join('\n');

return [{
  json: {
    text: report,
    llm_commentary: useLlm ? 'included' : 'omitted',
    guard_problems: problems,
    rejected_llm_commentary: useLlm ? null : llmText,
  },
}];

// ============================================================
// STEP 4a: Policy audit + policy chunks for RAG
// n8n Code node "Policy_Audit_JS"  |  Mode: "Run Once for All Items"
// Input : one item per policy PDF (text from "Extract_Policy_Text"), in the order of "Policy_Docs_JS"
//         Flow: Pricing_Engine_JS -> Policy_Source_JS -> Policy_Commit -> Policy_Manifest -> Policy_Docs_JS
//               -> Fetch_Policy_PDF -> Extract_Policy_Text -> this node
// Output: ONE item = the engine output + policy_audit + policy_rag (inputs for the embedding call)
// The policy lives in git (PDF documents + policy-manifest.json). To change a rule, commit a new
// version of those files; do not edit this node.
// ============================================================

const CONFIG = {
  MAX_NOTES: 12,  // at most this many SKUs get an AI-assisted clause review per run
  TOP_K: 3,       // clauses retrieved per SKU (used by the next node)
  // Lines that repeat on every PDF page and must not become part of a clause
  PAGE_NOISE: /^(Page \d+( of \d+)?|Retail Pricing and Markdown Policy\b.*)$/i,
  // Parameters the audit needs; the manifest must provide all of them
  REQUIRED_PARAMS: ['min_markup_by_department', 'default_min_markup', 'max_markdown_per_run', 'min_markdown_pct_to_act',
    'approval_threshold_pct', 'price_change_cooldown_days', 'competitor_undercut', 'competitor_outlier_low',
    'fast_mover_max_cover_weeks', 'fast_mover_max_age_days', 'clearance_min_age_days', 'clearance_min_cover_weeks',
    'price_ending_digit'],
};

const engine = $('Pricing_Engine_JS').first().json;
const results = engine.results;
if (!Array.isArray(results)) {
  throw new Error("Policy_Audit_JS expects the output of Pricing_Engine_JS (missing 'results').");
}

// ---------- 1. Manifest: version, parameters and the list of documents ----------
const manifest = $('Policy_Manifest').first().json;
const P = manifest.parameters;
if (!P || typeof P !== 'object') throw new Error("policy-manifest.json has no 'parameters' object.");
const missing = CONFIG.REQUIRED_PARAMS.filter((k) => P[k] === undefined || P[k] === null);
if (missing.length) throw new Error('policy-manifest.json is missing parameters: ' + missing.join(', '));
const policyVersion = String(manifest.version || 'unknown');
const policyCommit = ($('Policy_Commit').first().json.sha) || null;

const docs = $('Policy_Docs_JS').all().map((i) => i.json);
const texts = $input.all().map((i) => String((i.json || {}).text || ''));
if (docs.length !== texts.length) {
  throw new Error(`Expected text for ${docs.length} policy documents but got ${texts.length}. Check 'Fetch_Policy_PDF' and 'Extract_Policy_Text'.`);
}

// ---------- 2. Policy chunks: one chunk per numbered clause ("P-4.1 Approval threshold") ----------
const chunks = [];
const seen = new Map();
const docSummary = [];
docs.forEach((doc, di) => {
  if (!texts[di].trim()) {
    throw new Error(`The policy document '${doc.file}' produced no text. A scanned PDF without a text layer cannot be read.`);
  }
  const lines = texts[di].replace(/\r/g, '').replace(/\f/g, '\n').split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !CONFIG.PAGE_NOISE.test(l));
  let cur = null;
  const found = [];
  const flush = () => { if (cur) { chunks.push(cur); found.push(cur.id); cur = null; } };
  for (const line of lines) {
    const h = line.match(/^(P-\d+\.\d+)\s+(.+)$/);
    if (h) {
      flush();
      if (seen.has(h[1])) throw new Error(`Clause ${h[1]} appears in both '${seen.get(h[1])}' and '${doc.file}'. Clause IDs must be unique across documents.`);
      seen.set(h[1], doc.file);
      cur = { id: h[1], title: h[2].trim(), text: '', doc: doc.file, doc_title: doc.title };
      continue;
    }
    if (/^\d+\.\s+[A-Z]/.test(line)) { flush(); continue; }   // section heading
    if (cur) cur.text += (cur.text ? ' ' : '') + line;
  }
  flush();
  if (!found.length) throw new Error(`No clauses found in '${doc.file}'. Clauses must start with an ID such as "P-4.1 Approval threshold".`);
  docSummary.push({ file: doc.file, title: doc.title, clauses: found.length });
});
if (!chunks.length) throw new Error('No policy clauses were loaded.');

// ---------- 3. Deterministic audit: recompute each rule from the policy parameters ----------
const round2 = (n) => Math.round(n * 100) / 100;
const sek = (n) => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const violations = [];
const add = (r, clause, message) => violations.push({ sku: r.sku, clause, message });

for (const r of results) {
  const cur0 = r.current_price_sek, rec = r.recommended_price_sek, cost = r.cost_price_sek;
  const changed = rec < cur0;
  const md = ((cur0 - rec) / cur0) * 100;
  const markup = P.min_markup_by_department[r.department] ?? P.default_min_markup;
  const floor = round2(cost * (1 + markup));

  if (Math.abs((r.margin_floor_sek ?? floor) - floor) > 0.011) {
    add(r, 'P-2.1', `engine floor ${sek(r.margin_floor_sek)} SEK differs from the policy floor ${sek(floor)} SEK`);
  }
  if (rec > cur0) add(r, 'P-3.4', `recommended price ${sek(rec)} is above the current price ${sek(cur0)}`);
  if (changed) {
    if (rec + 0.001 < floor) add(r, 'P-2.1', `recommended price ${sek(rec)} is below the policy floor ${sek(floor)}`);
    if (md > P.max_markdown_per_run * 100 + 0.001) add(r, 'P-3.1', `markdown ${md.toFixed(1)}% is above the ${P.max_markdown_per_run * 100}% maximum`);
    if (md < P.min_markdown_pct_to_act - 0.001) add(r, 'P-3.2', `markdown ${md.toFixed(1)}% is below the minimum step`);
    if (Math.round(rec) % 10 !== P.price_ending_digit) add(r, 'P-3.3', `price ${sek(rec)} does not end in ${P.price_ending_digit}`);
    const cover = r.weeks_of_cover === null || r.weeks_of_cover === undefined ? Infinity : r.weeks_of_cover;
    if (cover <= P.fast_mover_max_cover_weeks && r.days_in_stock <= P.fast_mover_max_age_days) {
      add(r, 'P-6.1', 'fast mover was marked down');
    }
  }
  const expectApproval = md >= P.approval_threshold_pct - 1e-9;
  if (Boolean(r.approval_required) !== expectApproval) {
    add(r, 'P-4.1', `approval flag is ${r.approval_required} but a ${md.toFixed(1)}% markdown ${expectApproval ? 'requires' : 'does not require'} approval`);
  }
  const coverC = r.weeks_of_cover === null || r.weeks_of_cover === undefined ? Infinity : r.weeks_of_cover;
  const expectClearance = changed && r.days_in_stock >= P.clearance_min_age_days && coverC >= P.clearance_min_cover_weeks;
  if ((r.action === 'CLEARANCE') !== expectClearance) {
    add(r, 'P-8.1', `action is ${r.action} but the clearance criteria ${expectClearance ? 'are' : 'are not'} met`);
  }
}

// ---------- 4. Which SKUs get a clause review ----------
const violationsBySku = {};
violations.forEach((v) => { (violationsBySku[v.sku] = violationsBySku[v.sku] || []).push(v); });
const score = (r) => (violationsBySku[r.sku] ? 1000 : 0) + (r.action === 'REVIEW' ? 500 : 0)
  + (r.action === 'CLEARANCE' ? 300 : 0) + (r.approval_required ? 100 : 0) + r.markdown_percent;
const flaggedAll = results
  .filter((r) => violationsBySku[r.sku] || r.action === 'REVIEW' || r.recommended_price_sek < r.current_price_sek)
  .sort((a, b) => score(b) - score(a));
const flaggedSel = flaggedAll.slice(0, CONFIG.MAX_NOTES);

const flagged = flaggedSel.map((r) => {
  const stockAtCost = r.units_in_stock * r.cost_price_sek;
  const cover = r.weeks_of_cover === null || r.weeks_of_cover === undefined ? 'no recent sales' : `${r.weeks_of_cover} weeks of cover`;
  const summary =
    `${r.sku} (${r.product_name}), department ${r.department}, category ${r.category}. Action ${r.action}. ` +
    `Price ${sek(r.current_price_sek)} to ${sek(r.recommended_price_sek)} SEK, markdown ${r.markdown_percent}%. ` +
    `${r.days_in_stock} days in stock, ${cover}. Stock at cost ${sek(stockAtCost)} SEK. ` +
    `Needs approval at 15% or more: ${r.approval_required ? 'yes' : 'no'}.`;
  const query = `${r.department} ${r.category} ${r.product_name} ${r.action} markdown ${r.approval_required ? 'approval' : ''} ${stockAtCost > 150000 ? 'large stock exposure' : ''}`;
  return { sku: r.sku, department: r.department, action: r.action, approval_required: r.approval_required, summary, query: query.replace(/\s+/g, ' ').trim() };
});

const embedInputs = [
  ...chunks.map((c) => `search_document: ${c.id} ${c.title}. ${c.text}`),
  ...flagged.map((f) => `search_query: ${f.query}`),
];

return [{
  json: {
    ...engine,
    policy_audit: {
      policy_version: policyVersion,
      checked: results.length,
      violations,
      passed: violations.length === 0,
      policy_commit: policyCommit,
      policy_docs: docs.length,
      documents: docSummary,
    },
    policy_rag: {
      n_chunks: chunks.length,
      chunks,
      flagged,
      n_flagged_total: flaggedAll.length,
      embed_inputs: embedInputs,
    },
  },
}];

// ============================================================
// STEP 4b: Retrieve the relevant policy clauses for each flagged SKU
// n8n Code node "Policy_Retrieve_JS"  |  Mode: "Run Once for All Items"
// Input : the response of the "Embed_Policy" HTTP node (Ollama /api/embed)
// Output: one item per flagged SKU with a ready-to-use LLM prompt (or one "none" item)
// ============================================================

const TOP_K = 3;
const ctx = $('Policy_Audit_JS').first().json;
const { chunks, flagged, n_chunks } = ctx.policy_rag;
const resp = $input.first().json || {};
const emb = resp.embeddings;

const NONE_PROMPT = 'Reply with exactly: No policy issue.';
const none = (reason) => [{ json: { sku: null, none: true, rag_unavailable: reason || null, prompt: NONE_PROMPT, retrieved: [], allowed_text: '' } }];

if (!flagged.length) return none(null);
if (!Array.isArray(emb) || emb.length !== n_chunks + flagged.length) {
  // Graceful degradation: the report is still produced, without clause review
  return none(resp.error ? `embedding call failed: ${JSON.stringify(resp.error).slice(0, 120)}` : 'embedding response had an unexpected shape');
}

const cos = (a, b) => {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
};

const chunkVecs = emb.slice(0, n_chunks);
const runDate = $now.toFormat('yyyy-MM-dd');

return flagged.map((f, i) => {
  const q = emb[n_chunks + i];
  const scored = chunks.map((c, j) => ({ c, j })).filter(({ c }) => {
    // metadata filter: a clause that says "Applies to: <departments>" is only used for those departments
    const m = c.text.match(/^Applies to:\s*([^.]*)\./i);
    if (!m || /all departments/i.test(m[1])) return true;
    return m[1].toLowerCase().split(/,|\band\b/).map((x) => x.trim()).includes(f.department.toLowerCase());
  }).map(({ c, j }) => {
    let s = cos(q, chunkVecs[j]);
    const t = (c.title + ' ' + c.text).toLowerCase();
    if (t.includes(f.department.toLowerCase())) s += 0.08;                       // clause names this department
    if (t.includes(f.action.toLowerCase())) s += 0.08;                           // clause names this action
    if (f.approval_required && c.id.startsWith('P-4')) s += 0.05;                // approvals section
    return { c, s };
  }).sort((a, b) => b.s - a.s).slice(0, TOP_K);

  const retrieved = scored.map(({ c, s }) => ({ id: c.id, title: c.title, text: c.text, score: Math.round(s * 1000) / 1000 }));
  const clauseBlock = retrieved.map((c) => `[${c.id}] ${c.title}: ${c.text}`).join('\n');

  const prompt = [
    'You are a pricing policy reviewer. Use ONLY the policy clauses below.',
    '',
    `RUN DATE: ${runDate}`,
    'DECISION:',
    f.summary,
    '',
    'POLICY CLAUSES:',
    clauseBlock,
    '',
    'TASK: In one or two sentences, say which clause (if any) requires a human action for this decision, and what the action is.',
    'Cite clause IDs in square brackets, for example [P-4.1]. Never mention a clause that is not listed above.',
    'Use only numbers that appear above. If nothing needs attention, reply exactly: No policy issue.',
  ].join('\n');

  return { json: { sku: f.sku, none: false, prompt, retrieved, allowed_text: `${runDate} ${f.summary} ${clauseBlock}` } };
});

// ============================================================
// STEP 4c: Verify the AI clause notes and build the "Policy Review" section
// n8n Code node "Policy_Collect_JS"  |  Mode: "Run Once for All Items"
// Input : outputs of "Policy_Notes_Chain" (one item per retrieved SKU, same order)
// Output: ONE item = the engine output + policy_audit + policy_notes + policy_section_md
// ============================================================

const ctx = $('Policy_Audit_JS').first().json;
const retr = $('Policy_Retrieve_JS').all().map((i) => i.json);
const outs = $input.all().map((i) => i.json);
const results = ctx.policy_rag ? ctx.results : [];
const audit = ctx.policy_audit;
const clean = (s) => String(s).replace(/\|/g, '/').replace(/\s+/g, ' ').trim();

// ---------- helpers ----------
const productNames = ctx.results.map((r) => r.product_name).sort((a, b) => b.length - a.length);
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const scrub = (s) => {
  let t = s;
  for (const n of productNames) t = t.replace(new RegExp(esc(n), 'gi'), ' PRODUCT ');
  return t.replace(/P-\d+\.\d+/g, ' CLAUSE ').replace(/SKU[\s-]?\d+/gi, ' SKU ').replace(/\d{4}-\d{2}-\d{2}/g, ' DATE ');
};
const nums = (s) => (scrub(s).match(/\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?/g) || []).map((x) => parseFloat(x.replace(/,/g, '')));

// ---------- verify each note ----------
const notes = [];
const unavailable = retr.length && retr[0].rag_unavailable;

if (!unavailable) {
  retr.forEach((r, i) => {
    if (r.none) return;
    const raw = String((outs[i] && outs[i].text) || '').trim();
    const ids = [...new Set(raw.match(/P-\d+\.\d+/g) || [])];
    const allowedIds = r.retrieved.map((c) => c.id);
    const allowedNums = new Set(nums(r.allowed_text));
    const problems = [];

    if (!raw) problems.push('no model output');
    const isNone = /^no policy issue\.?$/i.test(raw);
    if (raw && !isNone) {
      if (!ids.length) problems.push('no clause cited');
      ids.filter((id) => !allowedIds.includes(id)).forEach((id) => problems.push(`cites ${id}, which was not retrieved`));
      nums(raw).filter((n) => !allowedNums.has(n)).forEach((n) => problems.push(`number ${n} not in the decision or clauses`));
      if (raw.length > 450) problems.push('too long');
    }

    if (problems.length) {
      notes.push({
        sku: r.sku, source: 'fallback', problems, retrieved: allowedIds,
        text: 'Relevant clauses: ' + r.retrieved.map((c) => `[${c.id}] ${c.title}`).join('; ') + '.',
      });
    } else {
      notes.push({ sku: r.sku, source: 'llm', problems: [], retrieved: allowedIds, text: isNone ? 'No policy issue.' : raw });
    }
  });
}

// ---------- Policy Review section ----------
const lines = [];
lines.push(`**Policy audit (policy v${audit.policy_version}, commit ${audit.policy_commit ? String(audit.policy_commit).slice(0, 7) : 'unknown'}, ${audit.policy_docs} documents):** ${audit.checked} SKU decisions recomputed against the policy parameters. ` +
  (audit.passed ? 'No violations.' : `${audit.violations.length} violation${audit.violations.length === 1 ? '' : 's'}.`));
if (!audit.passed) {
  lines.push('', ...audit.violations.map((v) => `- ${v.sku}, [${v.clause}]: ${v.message}`));
}

lines.push('');
if (unavailable) {
  lines.push(`**Clause review:** unavailable this run (${unavailable}). The policy audit above is unaffected.`);
} else if (!notes.length) {
  lines.push('**Clause review:** no SKU needed a clause review.');
} else {
  const total = ctx.policy_rag.n_flagged_total;
  const okCount = notes.filter((n) => n.source === 'llm').length;
  lines.push(`**Clause review (AI-assisted, citations verified):** ${notes.length} of ${total} flagged SKUs reviewed; ${okCount} written by the local LLM, ${notes.length - okCount} replaced by the list of retrieved clauses because the text failed verification.`);
  lines.push('', '| SKU | Action | Clauses retrieved | Policy note |', '| --- | --- | --- | --- |');
  for (const n of notes) {
    const r = ctx.results.find((x) => x.sku === n.sku) || {};
    lines.push(`| ${n.sku} | ${r.action || ''} | ${n.retrieved.join(', ')} | ${clean(n.text)}${n.source === 'fallback' ? ' _(auto)_' : ''} |`);
  }
}

const { policy_rag, ...rest } = ctx;   // drop the bulky embedding inputs
return [{
  json: {
    ...rest,
    policy_notes: notes,
    policy_rag_summary: { n_chunks: policy_rag.n_chunks, n_flagged_total: policy_rag.n_flagged_total, reviewed: notes.length },
    policy_section_md: lines.join('\n'),
  },
}];

// ============================================================
// Report_HTML_JS - interactive HTML report (no external libraries)
// n8n Code node | Mode: "Run Once for All Items"
// Place it AFTER "Report_Assembly_JS", in parallel with "Create a file".
// Output: { html } -> commit with a second GitHub "Create a file" node
// (fileContent = {{ $json.html }}, filePath ending in .html).
// ============================================================

const engine = $('Pricing_Engine_JS').first().json;
const F = engine.facts;
const R = engine.results;
const validated = $('Validate & Normalise').all().map((i) => i.json);
let policyMd = '';
try { policyMd = $('Policy_Collect_JS').first().json.policy_section_md || ''; } catch (e) { policyMd = ''; }
let llmStatus = 'omitted';
try { llmStatus = $('Report_Assembly_JS').first().json.llm_commentary || 'omitted'; } catch (e) { /* optional */ }
let graph = { available: false };
try { graph = $('Graph_Sync_JS').first().json.graph || graph; } catch (e) { /* graph is optional */ }
const meta = {};
validated.forEach((v) => { meta[v.sku] = v; });

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const sek = (n) => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '\u00a0');
const md = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/_(.+?)_/g, '<i>$1</i>');

// ---------- KPI cards ----------
const kpi = (label, value, sub) =>
  '<div class="kpi"><div class="kl">' + label + '</div><div class="kv">' + value + '</div><div class="ks">' + sub + '</div></div>';
const kpis = [
  kpi('SKUs analysed', F.skus, F.changed_count + ' with a price change'),
  kpi('Needs approval', F.approvals_count, 'markdown of ' + F.approval_threshold_pct + '% or more'),
  kpi('Average markdown', F.avg_markdown_pct + '%', 'largest ' + F.top_markdown_pcts[0] + '%'),
  kpi('Capital tied up', sek(F.capital_tied) + ' SEK', 'at cost, marked-down SKUs'),
  kpi('Recoverable', sek(F.recoverable) + ' SEK', 'at recommended prices'),
  kpi('Revenue given up', sek(F.revenue_given_up) + ' SEK', 'versus current prices'),
].join('');

// ---------- action mix bar ----------
const mix = [['HOLD', F.hold], ['MARKDOWN', F.markdown], ['CLEARANCE', F.clearance], ['REVIEW', F.review]]
  .filter((m) => m[1] > 0)
  .map((m) => '<div class="seg a-' + m[0] + '" style="flex:' + m[1] + '" title="' + m[0] + '">' + m[0].charAt(0) + m[0].slice(1).toLowerCase() + ' ' + m[1] + '</div>')
  .join('');

// ---------- revenue given up by department ----------
const dep = {};
R.forEach((r) => {
  const d = dep[r.department] || (dep[r.department] = { n: 0, changed: 0, given: 0, sum: 0 });
  d.n++;
  if (r.markdown_percent > 0) {
    d.changed++;
    d.sum += r.markdown_percent;
    d.given += (r.current_price_sek - r.recommended_price_sek) * r.units_in_stock;
  }
});
const deps = Object.entries(dep).sort((a, b) => b[1].given - a[1].given);
const maxGiven = Math.max(...deps.map((d) => d[1].given), 1);
const depHtml = deps.map(([name, d]) =>
  '<div class="drow"><div class="dn">' + esc(name) + '</div><div class="dbar"><span style="width:' + (d.given / maxGiven * 100).toFixed(1) + '%"></span></div>' +
  '<div class="dv">' + sek(d.given) + ' SEK<small>avg ' + (d.changed ? (d.sum / d.changed).toFixed(1) : '0') + '% on ' + d.changed + ' of ' + d.n + ' SKUs</small></div></div>'
).join('');

// ---------- policy section (markdown -> html) ----------
let policyHtml = '';
if (policyMd) {
  const lines = policyMd.split('\n').filter((l) => l.trim());
  const tbl = lines.filter((l) => l.trim().startsWith('|') && !/^\|\s*-/.test(l.trim()));
  const paras = lines.filter((l) => !l.trim().startsWith('|')).map((l) => '<p>' + md(l) + '</p>').join('');
  const rows = tbl.map((l, i) => {
    const c = l.trim().replace(/^\||\|$/g, '').split('|').map((x) => x.trim());
    const tag = i === 0 ? 'th' : 'td';
    return '<tr>' + c.map((x) => '<' + tag + '>' + md(x) + '</' + tag + '>').join('') + '</tr>';
  }).join('');
  policyHtml = paras + (rows ? '<div class="scroll"><table class="plain">' + rows + '</table></div>' : '');
}

// ---------- data quality ----------
const rejected = validated.filter((v) => v.validation_status !== 'valid').length;
const warned = validated.filter((v) => v.validation_status === 'valid' && (v.validation_warnings || []).length);
const dqHtml = '<p>Received <b>' + validated.length + '</b> | accepted <b>' + (validated.length - rejected) + '</b> | rejected <b>' + rejected +
  '</b> | with warnings <b>' + warned.length + '</b></p>' +
  (warned.length ? '<ul>' + warned.map((v) => '<li><b>' + esc(v.sku) + '</b>: ' + esc(v.validation_warnings.join('; ')) + '</li>').join('') + '</ul>' : '');

// ---------- knowledge graph insights ----------
const th = (h) => '<tr>' + h.map((x) => '<th>' + x + '</th>').join('') + '</tr>';
const tbl = (head, body, empty) => body ? '<div class="scroll"><table class="plain">' + th(head) + body + '</table></div>' : '<p class="mu">' + empty + '</p>';
const vr = (x) => esc(x.product) + ' <span class="var">' + esc(x.variant) + '</span>';
let graphHtml = '<p>Graph not available for this run' + (graph.error ? ' (' + esc(graph.error) + ')' : '') + '. The decisions above do not depend on it.</p>';
if (graph.available) {
  const chips = graph.nodes.map((n) => '<span class="chip">' + esc(n.label) + ' <b>' + n.n + '</b></span>').join('');
  const reb = graph.rebalance.map((x) => '<tr><td>' + vr(x) + '</td><td>' + esc(x.surplus_store) + ': ' + x.surplus_cover + ' wk cover, -' + x.markdown + '%</td><td>' + esc(x.short_store) + ': ' + x.short_cover + ' wk cover</td><td class="num">' + sek(x.revenue_given_up) + '</td></tr>').join('');
  const gap = graph.price_gap.map((x) => '<tr><td>' + vr(x) + '</td><td class="num">' + sek(x.lo) + '</td><td class="num">' + sek(x.hi) + '</td><td class="num">' + x.gap_pct + '%</td><td>' + esc((x.offers || []).join(', ')) + '</td></tr>').join('');
  const maxC = Math.max(...graph.clauses.map((c) => c.decisions), 1);
  const cl = graph.clauses.map((c) => '<tr><td><b>' + esc(c.clause) + '</b></td><td>' + esc(c.title) + '</td><td><span class="mbar"><i style="width:' + (c.decisions / maxC * 100).toFixed(0) + '%"></i></span>' + c.decisions + '</td><td class="num">' + sek(c.revenue_given_up) + '</td></tr>').join('');
  const maxS = Math.max(...graph.stores.map((x) => x.revenue_given_up), 1);
  const stores = graph.stores.map((x) => '<div class="drow"><div class="dn">' + esc(x.store) + '</div><div class="dbar"><span style="width:' + (x.revenue_given_up / maxS * 100).toFixed(1) + '%"></span></div><div class="dv">' + sek(x.revenue_given_up) + ' SEK<small>avg ' + x.avg_markdown + '% on ' + x.skus + ' SKUs</small></div></div>').join('');
  graphHtml = '<p class="mu">Run ' + esc(graph.run_id) + ' | ' + graph.node_total + ' nodes and ' + graph.relationships + ' relationships in Neo4j</p><div>' + chips + '</div>' +
    '<h3>Move stock before you discount</h3><p class="mu">The same variant is marked down 15% or more in one store while another store is nearly sold out.</p>' +
    tbl(['Product', 'Surplus store', 'Short store', 'Revenue given up (SEK)'], reb, 'No transfer opportunities in this run.') +
    '<h3>Same product, different prices</h3><p class="mu">One variant (one GTIN) carries different current prices in different stores.</p>' +
    tbl(['Product', 'Lowest', 'Highest', 'Gap', 'Store prices'], gap, 'Prices are consistent across stores.') +
    '<h3>Policy clauses behind the decisions</h3>' + tbl(['Clause', 'Rule', 'Decisions', 'Revenue given up (SEK)'], cl, 'No clause links.') +
    '<h3>Revenue given up by store</h3>' + stores;
}

// ---------- management summary (plain language; built only from the calculated figures) ----------
const summaryHtml = (() => {
  const B = (x) => '<b>' + esc(x) + '</b>';
  const pl = (n, one, many) => n + ' ' + (n === 1 ? one : many);
  const cnt = (n, one, many) => B(n) + ' ' + (n === 1 ? one : many);
  const has = (r, p) => (r.reasons || []).some((x) => x.startsWith(p));
  const chg = R.filter((r) => r.action === 'MARKDOWN' || r.action === 'CLEARANCE');
  const held = R.filter((r) => r.action === 'HOLD');
  const reviewRows = R.filter((r) => r.action === 'REVIEW');
  let audit = null;
  try { audit = $('Policy_Collect_JS').first().json.policy_audit || null; } catch (e) { audit = null; }
  const p = [];

  // 1. Headline
  if (chg.length) {
    p.push('<p class="lead">This run reviewed ' + B(pl(F.skus, 'product (SKU)', 'products (SKUs)')) + ' and recommends lowering the price of ' + B(chg.length) +
      '. The stock in those products cost ' + B(sek(F.capital_tied) + ' SEK') + ' to buy and would bring in about ' + B(sek(F.recoverable) + ' SEK') +
      ' if all of it sells at the new prices. The price reductions give up ' + B(sek(F.revenue_given_up) + ' SEK') + ' of revenue compared with today\u2019s prices.</p>');
  } else {
    p.push('<p class="lead">This run reviewed ' + B(pl(F.skus, 'product (SKU)', 'products (SKUs)')) + ' and recommends ' + B('no price changes') + '.</p>');
  }

  // 2. What was checked and the result
  const outcome = [B(pl(F.hold, 'SKU keeps', 'SKUs keep')) + ' the current price'];
  if (F.markdown) outcome.push(B(pl(F.markdown, 'gets a markdown', 'get a markdown')) + ' (a price reduction)');
  if (F.clearance) outcome.push(B(pl(F.clearance, 'goes', 'go')) + ' on clearance (a larger reduction for old stock that sells slowly)');
  if (F.review) outcome.push(B(pl(F.review, 'needs', 'need')) + ' a manual look because today\u2019s price is already below the minimum margin');
  p.push('<h3>What was done</h3><p>Each product was checked on four things: how long it has been in stock, how many weeks the stock on hand would last at the recent sales pace, what competitors charge, and whether the price still leaves the minimum margin required for its department. The result: ' +
    outcome.join('; ') + '.</p>');

  // 3. Why prices change / stay
  const comp = chg.filter((r) => has(r, 'Cheapest credible competitor')).length;
  const stock = chg.filter((r) => has(r, 'Stock pressure')).length;
  const capped = chg.filter((r) => has(r, 'Capped at')).length;
  const floored = chg.filter((r) => has(r, 'Limited by margin floor')).length;
  const fast = held.filter((r) => has(r, 'Fast mover')).length;
  const cool = held.filter((r) => has(r, 'Price changed')).length;
  const nostock = held.filter((r) => has(r, 'No stock on hand')).length;
  const small = held.filter((r) => has(r, 'Calculated change below')).length;
  const why = [];
  if (chg.length) {
    const drivers = [];
    if (comp) drivers.push('a competitor sells the same item for less in ' + B(comp) + ' of the ' + chg.length);
    if (stock) drivers.push('the stock is old, or large compared with how fast it sells, in ' + B(stock));
    if (drivers.length) why.push('Among the price reductions, ' + drivers.join(', and ') + ' (some products have both reasons).');
    const limits = [];
    if (capped) limits.push(cnt(capped, 'reduction was', 'reductions were') + ' held back by the ' + F.max_markdown_pct + '% limit per run');
    if (floored) limits.push(cnt(floored, 'was', 'were') + ' limited by the department\u2019s minimum margin');
    if (limits.length) why.push(limits.join(', and ').replace(/^<b>/, '<b>').replace(/^(<b>\d+<\/b> )/, '$1') + '.');
  }
  const keeps = [];
  if (fast) keeps.push(cnt(fast, 'sells quickly and is', 'sell quickly and are') + ' left alone');
  if (cool) keeps.push(cnt(cool, 'had', 'had') + ' a price change too recently');
  if (nostock) keeps.push(cnt(nostock, 'has', 'have') + ' no stock');
  if (small) keeps.push(cnt(small, 'would', 'would') + ' change by too little to matter');
  if (keeps.length) why.push('Of the ' + F.hold + ' products that keep their price, ' + keeps.join(', ') + '.');
  if (why.length) p.push('<h3>Why prices change, or stay</h3><p>' + why.join(' ') + '</p>');

  // 4. Financial meaning
  if (chg.length) {
    const margin = F.recoverable - F.capital_tied;
    const marginPct = F.recoverable ? margin / F.recoverable * 100 : 0;
    const depth = (F.recoverable + F.revenue_given_up) ? F.revenue_given_up / (F.recoverable + F.revenue_given_up) * 100 : 0;
    p.push('<h3>What it means financially</h3><p>Selling this stock at the new prices would still leave a gross margin of ' + B(sek(margin) + ' SEK') + ' (' + marginPct.toFixed(1) + '% of the revenue) after the ' + sek(F.capital_tied) + ' SEK it cost to buy. The average price reduction is ' + B(F.avg_markdown_pct + '%') +
      ' per product (the largest is ' + F.top_markdown_pcts[0] + '%), which is ' + depth.toFixed(1) + '% of the current selling value of this stock. ' +
      'These figures assume all units are sold; they do not say how long that will take.</p>');
  }

  // 5. Where the impact sits
  const depRows = deps.filter((d) => d[1].given > 0);
  if (chg.length && depRows.length) {
    const totalGiven = depRows.reduce((s, d) => s + d[1].given, 0) || 1;
    const share = (d) => (d[1].given / totalGiven * 100).toFixed(0) + '%';
    let t = B(depRows[0][0]) + ' carries the largest share of the revenue given up (' + sek(depRows[0][1].given) + ' SEK, ' + share(depRows[0]) + ' of the total)';
    if (depRows[1]) t += ', followed by ' + B(depRows[1][0]) + ' (' + sek(depRows[1][1].given) + ' SEK, ' + share(depRows[1]) + ')';
    t += '.';
    const top3 = [...chg].sort((a, b) => b.markdown_percent - a.markdown_percent).slice(0, 3)
      .map((r) => esc(r.product_name) + ' (' + esc(r.sku) + ', ' + r.markdown_percent + '%)').join('; ');
    p.push('<h3>Where the impact is</h3><p>' + t + ' The deepest reductions are ' + top3 + '.</p>');
  }

  // 6. Decisions needed
  const todo = [];
  if (audit && audit.violations && audit.violations.length) {
    todo.push(B(pl(audit.violations.length, 'decision breaks', 'decisions break')) + ' the written pricing policy. Resolve this before acting on the report (see Policy review).');
  }
  if (F.approvals_count) {
    const sharePct = chg.length ? (F.approvals_count / chg.length * 100).toFixed(0) : '0';
    todo.push(B(F.approvals_count) + ' of the ' + chg.length + ' price reductions (' + sharePct + '%) are ' + F.approval_threshold_pct + '% or more and need human approval before any price is changed. They are flagged in the Pricing actions table.');
  }
  if (reviewRows.length) {
    const names = reviewRows.slice(0, 5).map((r) => esc(r.product_name) + ' (' + esc(r.sku) + ')').join(', ') + (reviewRows.length > 5 ? ' and ' + (reviewRows.length - 5) + ' more' : '');
    todo.push(B(pl(reviewRows.length, 'product is', 'products are')) + ' already priced below the minimum margin and need a decision from the pricing team: ' + names + '.');
  }
  if (rejected) todo.push(B(pl(rejected, 'data row was', 'data rows were')) + ' rejected and not priced; see Data quality.');
  if (warned.length) todo.push(B(pl(warned.length, 'row has', 'rows have')) + ' data warnings (for example missing competitor prices or product IDs). They were still priced; see Data quality.');
  if (graph && graph.available && Array.isArray(graph.rebalance) && graph.rebalance.length) {
    todo.push(B(pl(graph.rebalance.length, 'product variant is', 'product variants are')) + ' overstocked in one store while another store is nearly sold out. Moving stock between stores may avoid some of the discounting (see Knowledge graph insights).');
  }
  p.push('<h3>What needs attention</h3>' + (todo.length ? '<ul>' + todo.map((x) => '<li>' + x + '</li>').join('') + '</ul>' : '<p>Nothing beyond the normal review by the pricing team.</p>'));

  // 7. How reliable this is
  let rel = 'All prices are calculated by fixed rules, not by AI. The rules never raise a price, never reduce a price below the department\u2019s minimum margin, and limit any single reduction to ' + F.max_markdown_pct + '% per run. ';
  if (audit && audit.checked !== undefined) {
    const nv = (audit.violations || []).length;
    rel += 'As a second check, every decision was recomputed against the written pricing policy (version ' + esc(audit.policy_version || 'unknown') +
      (audit.policy_commit ? ', commit ' + esc(String(audit.policy_commit).slice(0, 7)) : '') + (audit.policy_docs ? ', ' + audit.policy_docs + ' documents' : '') + '): ' +
      (nv ? B(pl(nv, 'violation', 'violations')) + ' found. ' : 'no violations found. ');
  }
  rel += 'Nothing is changed automatically: these are recommendations for the pricing team.';
  p.push('<h3>How reliable this is</h3><p>' + rel + '</p>');

  // 8. Glossary
  p.push('<p class="mu"><b>How to read this report.</b> Markdown: a price reduction. Clearance: a larger reduction for old stock that sells slowly. Weeks of cover: how many weeks the stock on hand would last at the recent sales pace. Capital tied up: what the stock cost to buy. Recoverable: the cash the stock would bring in at the recommended prices. Revenue given up: the difference between today\u2019s prices and the recommended prices.</p>');
  return p.join('');
})();

const data = R.map((r) => ({
  variant: (meta[r.sku] || {}).variant || '', store: (meta[r.sku] || {}).store || '', category: r.category,
  subcategory: (meta[r.sku] || {}).subcategory || '', clauses: (graph.lineage || {})[r.sku] || [],
  sku: r.sku, product_name: r.product_name, department: r.department, action: r.action,
  current_price_sek: r.current_price_sek, recommended_price_sek: r.recommended_price_sek,
