<script>
var D=%%DATA%%;
var flt="ALL",q="",key="markdown_percent",dir=-1,open={};
var cols=[["sku","SKU"],["product_name","Product"],["store","Store"],["department","Department"],["action","Action"],["current_price_sek","Current"],["recommended_price_sek","Recommended"],["markdown_percent","Markdown"],["profit_margin_percent","Margin"],["weeks_of_cover","Cover (wk)"],["days_in_stock","Days"]];
var numeric={current_price_sek:1,recommended_price_sek:1,markdown_percent:1,profit_margin_percent:1,weeks_of_cover:1,days_in_stock:1};
function fmt(n){return Math.round(n).toLocaleString("en-US").replace(/,/g,"\u00a0")}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
var filters=["ALL","HOLD","MARKDOWN","CLEARANCE","REVIEW","APPROVAL"];
function count(f){return D.filter(function(r){return pass(r,f)}).length}
function pass(r,f){return f==="ALL"||(f==="APPROVAL"?r.approval_required:r.action===f)}
function tools(){var h="";filters.forEach(function(f){h+='<button data-f="'+f+'" class="'+(f===flt?"on":"")+'">'+(f==="APPROVAL"?"Needs approval":f.charAt(0)+f.slice(1).toLowerCase())+" "+count(f)+"</button>"});
h+='<input id="q" placeholder="Search SKU, product, department" value="'+esc(q)+'">';document.getElementById("tools").innerHTML=h}
function head(){var h="<tr>";cols.forEach(function(c){var a=key===c[0]?(dir>0?" \u25B2":" \u25BC"):"";h+='<th data-k="'+c[0]+'" class="'+(numeric[c[0]]?"num":"")+'">'+c[1]+a+"</th>"});
document.querySelector("#t thead").innerHTML=h+"</tr>"}
function body(){var s=q.toLowerCase();var rows=D.filter(function(r){return pass(r,flt)&&(!s||(r.sku+" "+r.product_name+" "+r.variant+" "+r.store+" "+r.department).toLowerCase().indexOf(s)>-1)});
rows.sort(function(a,b){var x=a[key],y=b[key];return (typeof x==="string"?x.localeCompare(y):x-y)*dir});
var h="";rows.forEach(function(r){var m=r.markdown_percent;
h+='<tr class="row" data-s="'+r.sku+'"><td>'+r.sku+'</td><td>'+esc(r.product_name)+(r.variant?' <span class="var">'+esc(r.variant)+'</span>':'')+'</td><td>'+esc(r.store)+'</td><td>'+esc(r.department)+'</td><td><span class="badge a-'+r.action+'">'+r.action+"</span>"+(r.approval_required?'<span class="flag" title="Needs approval">&#9873;</span>':"")+"</td>"+
'<td class="num">'+fmt(r.current_price_sek)+'</td><td class="num">'+fmt(r.recommended_price_sek)+'</td><td class="num"><span class="mbar"><i style="width:'+Math.min(m*4,100)+'%"></i></span>'+m+"%</td>"+
'<td class="num">'+r.profit_margin_percent+'%</td><td class="num">'+r.weeks_of_cover+'</td><td class="num">'+r.days_in_stock+"</td></tr>";
if(open[r.sku])h+='<tr class="det"><td colspan="11">'+detail(r)+"</td></tr>"});
document.querySelector("#t tbody").innerHTML=h||'<tr><td colspan="11">No matching SKUs</td></tr>'}
function detail(r){
var path=[r.department,r.category,r.subcategory,r.product_name,r.variant,r.sku+(r.store?" @ "+r.store:"")].filter(Boolean).map(esc).join(" &rsaquo; ");
var cl=r.clauses.length?r.clauses.map(esc).join(", "):"none";
var sib=D.filter(function(x){return x.product_name===r.product_name&&x.variant===r.variant&&x.sku!==r.sku}).map(function(x){return esc(x.store)+" "+x.action+" ("+x.weeks_of_cover+" wk cover)"}).join(", ")||"not stocked elsewhere";
return "<div><b>Path in the graph:</b> "+path+" &rarr; "+esc(r.action)+" &rarr; clauses "+cl+"</div><div><b>Why:</b> "+esc(r.reasons.join(" | "))+"</div><div><b>Same variant elsewhere:</b> "+sib+"</div>"}
function draw(){tools();head();body()}
document.addEventListener("click",function(e){var b=e.target.closest("button[data-f]");if(b){flt=b.dataset.f;draw();return}
var th=e.target.closest("th[data-k]");if(th){var k=th.dataset.k;dir=key===k?-dir:(numeric[k]?-1:1);key=k;head();body();return}
var tr=e.target.closest("tr.row");if(tr){open[tr.dataset.s]=!open[tr.dataset.s];body()}});
document.addEventListener("input",function(e){if(e.target.id==="q"){q=e.target.value;body()}});
draw();
</script></body></html>`;

const html = TEMPLATE
  .replace('%%DATE%%', esc(new Date().toISOString().slice(0, 16).replace('T', ' ')))
  .replace('%%KPIS%%', () => kpis)
  .replace('%%SUMMARY%%', () => summaryHtml)
  .replace('%%MIX%%', () => mix)
  .replace('%%DEPS%%', () => depHtml)
  .replace('%%POLICY%%', () => policyHtml || '<p>Policy review not available for this run.</p>')
  .replace('%%DQ%%', () => dqHtml)
  .replace('%%GRAPH%%', () => graphHtml)
  .replace('%%LLM%%', esc(llmStatus))
  .replace('%%DATA%%', () => JSON.stringify(data).replace(/</g, '\\u003c'));

return [{ json: { html } }];

// ============================================================
// Graph_Sync_JS - writes the run into Neo4j and reads back insights
// n8n Code node | Mode: "Run Once for All Items"
// Place it between "Policy_Collect_JS" and "Basic LLM Chain".
// It passes its input through unchanged and adds a "graph" field, so the
// pipeline keeps working even when Neo4j is down (graph.available = false).
// Needs: Neo4j 5.x with the Query API on port 7474 (see docker-compose).
// ============================================================

//const NEO4J = {
//  url: 'http://host.docker.internal:7474/db/neo4j/query/v2', // n8n and Neo4j run as separate "docker run" containers on a Mac
//  user: 'neo4j',
// password: '!SampleAiProject',
//};

const NEO4J = {
  url: 'http://host.docker.internal:7474/db/neo4j/query/v2', // Uses the Docker container name
  user: 'neo4j',
  password: '!SampleAiProject',
};

const engine = $('Pricing_Engine_JS').first().json;
const validated = $('Validate & Normalise').all().map((i) => i.json).filter((v) => v.validation_status === 'valid');
const meta = {};
validated.forEach((v) => { meta[v.sku] = v; });
const RUN_ID = new Date().toISOString().slice(0, 19);

// ---------- policy clauses (from the policy document) ----------
const CLAUSES = [
  ['P-2.1', 'Minimum markup over cost', '2 Margin protection'], ['P-2.2', 'Items priced below the minimum', '2 Margin protection'],
  ['P-3.1', 'Maximum markdown per run', '3 Price changes'], ['P-4.1', 'Approval threshold', '4 Approvals'],
  ['P-4.2', 'Clearance in Furniture and Electronics', '4 Approvals'], ['P-4.3', 'REVIEW items', '4 Approvals'],
  ['P-4.4', 'Large stock exposure', '4 Approvals'], ['P-5.1', 'Cooldown', '5 Timing'],
  ['P-6.1', 'Fast movers', '6 Demand and stock'], ['P-6.2', 'Stock pressure', '6 Demand and stock'],
  ['P-7.1', 'Undercutting', '7 Competition'], ['P-8.1', 'Clearance criteria', '8 Clearance'],
].map((c) => ({ id: c[0], title: c[1], section: c[2] }));

// Deterministic decision -> clause mapping (no LLM). Better long term: let the engine emit clause IDs.
function clausesFor(r) {
  const ids = new Set();
  const why = (r.reasons || []).join(' | ');
  if (r.approval_required) ids.add('P-4.1');
  if (r.action === 'CLEARANCE') { ids.add('P-8.1'); if (['Furniture', 'Electronics'].includes(r.department)) ids.add('P-4.2'); }
  if (r.action === 'REVIEW') { ids.add('P-2.2'); ids.add('P-4.3'); }
  if (/Fast mover/i.test(why)) ids.add('P-6.1');
  if (/cooldown/i.test(why)) ids.add('P-5.1');
  if (/Capped at/i.test(why)) ids.add('P-3.1');
  if (/margin floor/i.test(why)) ids.add('P-2.1');
  if (/competitor/i.test(why)) ids.add('P-7.1');
  if (/Stock pressure/i.test(why)) ids.add('P-6.2');
  if (r.markdown_percent > 0 && r.cost_price_sek * r.units_in_stock > 150000) ids.add('P-4.4');
  return [...ids];
}

const rows = engine.results.map((r) => {
  const m = meta[r.sku] || {};
  return {
    sku: r.sku, gtin: r.gtin || m.gtin || null,
    product_name: r.product_name, product_id: (m.brand || 'NoBrand') + '|' + r.product_name,
    variant: m.variant || 'Standard', variant_id: (m.brand || 'NoBrand') + '|' + r.product_name + '|' + (m.variant || 'Standard'),
    store: m.store || 'Unknown', brand: m.brand || 'Unknown', supplier: m.supplier || 'Unknown',
    department: r.department, category: r.category, subcategory: m.subcategory || 'General',
    current_price: r.current_price_sek, recommended_price: r.recommended_price_sek, markdown_percent: r.markdown_percent,
    cost_price: r.cost_price_sek, units_in_stock: r.units_in_stock, days_in_stock: r.days_in_stock, weeks_of_cover: r.weeks_of_cover,
    action: r.action, approval_required: !!r.approval_required, reasons: (r.reasons || []).join(' | '),
    revenue_given_up: Math.round((r.current_price_sek - r.recommended_price_sek) * r.units_in_stock),
    clauses: clausesFor(r),
  };
});

// ---------- Cypher ----------
const CONSTRAINTS = [
  'CREATE CONSTRAINT sku_key IF NOT EXISTS FOR (n:SKU) REQUIRE n.sku IS UNIQUE',
  'CREATE CONSTRAINT variant_key IF NOT EXISTS FOR (n:Variant) REQUIRE n.id IS UNIQUE',
  'CREATE CONSTRAINT product_key IF NOT EXISTS FOR (n:Product) REQUIRE n.id IS UNIQUE',
  'CREATE CONSTRAINT decision_key IF NOT EXISTS FOR (n:Decision) REQUIRE n.id IS UNIQUE',
  'CREATE CONSTRAINT clause_key IF NOT EXISTS FOR (n:Clause) REQUIRE n.id IS UNIQUE',
];
const LOAD_CLAUSES = 'UNWIND $clauses AS c MERGE (n:Clause {id: c.id}) SET n.title = c.title, n.section = c.section';
const LOAD = `
UNWIND $rows AS r
MERGE (dep:Department {name: r.department})
MERGE (cat:Category {id: r.department + '/' + r.category}) SET cat.name = r.category
MERGE (dep)-[:HAS_CATEGORY]->(cat)
MERGE (sub:Subcategory {id: r.department + '/' + r.category + '/' + r.subcategory}) SET sub.name = r.subcategory
MERGE (cat)-[:HAS_SUBCATEGORY]->(sub)
MERGE (b:Brand {name: r.brand})
MERGE (sup:Supplier {name: r.supplier})
MERGE (p:Product {id: r.product_id}) SET p.name = r.product_name
MERGE (sub)-[:HAS_PRODUCT]->(p)
MERGE (p)-[:BY_BRAND]->(b)
MERGE (p)-[:SUPPLIED_BY]->(sup)
MERGE (v:Variant {id: r.variant_id}) SET v.name = r.variant, v.gtin = coalesce(r.gtin, v.gtin)
MERGE (p)-[:HAS_VARIANT]->(v)
MERGE (st:Store {name: r.store})
MERGE (s:SKU {sku: r.sku})
SET s.current_price = r.current_price, s.cost_price = r.cost_price, s.units_in_stock = r.units_in_stock,
    s.days_in_stock = r.days_in_stock, s.weeks_of_cover = r.weeks_of_cover, s.gtin_missing = (r.gtin IS NULL)
MERGE (v)-[:STOCKED_AS]->(s)
MERGE (s)-[:AT_STORE]->(st)
MERGE (d:Decision {id: r.sku + '@' + $run_id})
SET d.run_id = $run_id, d.action = r.action, d.recommended_price = r.recommended_price, d.markdown_percent = r.markdown_percent,
    d.approval_required = r.approval_required, d.reasons = r.reasons, d.revenue_given_up = r.revenue_given_up
MERGE (s)-[:HAS_DECISION]->(d)
WITH d, r
UNWIND r.clauses AS cid
MATCH (c:Clause {id: cid})
MERGE (d)-[:BECAUSE_OF]->(c)`;

const INSIGHTS = {
  rebalance: `MATCH (p:Product)-[:HAS_VARIANT]->(v:Variant)-[:STOCKED_AS]->(a:SKU)-[:HAS_DECISION]->(da:Decision {run_id: $run_id}),
  (v)-[:STOCKED_AS]->(b:SKU)-[:HAS_DECISION]->(db:Decision {run_id: $run_id}),
  (a)-[:AT_STORE]->(sa:Store), (b)-[:AT_STORE]->(sb:Store)
WHERE da.action IN ['MARKDOWN','CLEARANCE'] AND da.markdown_percent >= 15 AND a.weeks_of_cover >= 20
  AND db.action = 'HOLD' AND b.weeks_of_cover < 4 AND b.units_in_stock > 0
RETURN p.name AS product, v.name AS variant, sa.name AS surplus_store, a.weeks_of_cover AS surplus_cover,
  da.markdown_percent AS markdown, da.revenue_given_up AS revenue_given_up, sb.name AS short_store, b.weeks_of_cover AS short_cover
ORDER BY revenue_given_up DESC LIMIT 8`,
  price_gap: `MATCH (p:Product)-[:HAS_VARIANT]->(v:Variant)-[:STOCKED_AS]->(s:SKU)-[:AT_STORE]->(st:Store)
WITH p, v, min(s.current_price) AS lo, max(s.current_price) AS hi, collect(st.name + ': ' + toString(s.current_price)) AS offers
WHERE hi > lo
RETURN p.name AS product, v.name AS variant, lo, hi, round(100.0 * (hi - lo) / lo, 1) AS gap_pct, offers
ORDER BY gap_pct DESC LIMIT 8`,
  clauses: `MATCH (d:Decision {run_id: $run_id})-[:BECAUSE_OF]->(c:Clause)
RETURN c.id AS clause, c.title AS title, count(d) AS decisions, sum(d.revenue_given_up) AS revenue_given_up
ORDER BY decisions DESC`,
  stores: `MATCH (st:Store)<-[:AT_STORE]-(s:SKU)-[:HAS_DECISION]->(d:Decision {run_id: $run_id})
RETURN st.name AS store, count(s) AS skus, sum(d.revenue_given_up) AS revenue_given_up, round(avg(d.markdown_percent), 1) AS avg_markdown
ORDER BY revenue_given_up DESC`,
  labels: 'MATCH (n) RETURN labels(n)[0] AS label, count(n) AS n ORDER BY n DESC',
  rels: 'MATCH ()-[r]->() RETURN count(r) AS n',
};

// ---------- Neo4j helper (handles plain and typed JSON replies) ----------
const plain = (v) => {
  if (Array.isArray(v)) return v.map(plain);
  if (v && typeof v === 'object') {
    if ('$type' in v && '_value' in v) return v.$type === 'Integer' ? Number(v._value) : plain(v._value);
    const o = {}; Object.keys(v).forEach((k) => { o[k] = plain(v[k]); }); return o;
  }
  return v;
};
const auth = 'Basic ' + Buffer.from(NEO4J.user + ':' + NEO4J.password).toString('base64');
const q = async (statement, parameters) => {
  const res = await this.helpers.httpRequest({
    method: 'POST', url: NEO4J.url, json: true, timeout: 20000,
    headers: { Authorization: auth, Accept: 'application/json', 'Content-Type': 'application/json' },
    body: { statement, parameters: parameters || {} },
  });
  const d = res.data || {};
  const fields = d.fields || [];
  return (d.values || []).map((row) => { const o = {}; fields.forEach((f, i) => { o[f] = plain(row[i]); }); return o; });
};

const input = $input.first().json;
let graph;
try {
  for (const c of CONSTRAINTS) await q(c);
  await q(LOAD_CLAUSES, { clauses: CLAUSES });
  await q(LOAD, { rows, run_id: RUN_ID });
  const p = { run_id: RUN_ID };
  const out = {};
  for (const k of Object.keys(INSIGHTS)) out[k] = await q(INSIGHTS[k], k === 'labels' || k === 'rels' ? {} : p);
  const lineage = {}; rows.forEach((r) => { lineage[r.sku] = r.clauses; });
  graph = {
    available: true, run_id: RUN_ID, lineage,
    nodes: out.labels, node_total: out.labels.reduce((a, x) => a + x.n, 0), relationships: out.rels[0] ? out.rels[0].n : 0,
    rebalance: out.rebalance, price_gap: out.price_gap, clauses: out.clauses, stores: out.stores,
  };
} catch (e) {
  graph = { available: false, error: String(e.message || e).slice(0, 300) };
}
return [{ json: { ...input, graph } }];

// ============================================================
// Policy_Source_JS - where the policy lives in git
// n8n Code node | Mode: "Run Once for All Items"
// Only this node knows the repository. Change the values below if you move the policy files.
// The policy is read at an exact commit (the latest one that touched the folder), so every report can say
// which policy version produced it.
// ============================================================
const SOURCE = {
  owner: 'thivakar-allimuthu',
  repo: 'enterprise-ai-lab',
  branch: 'main',                                       // check: the branch that holds the policy files
  path: 'case-studies/autonomous-pricing-markdown/policies',
};

const api = 'https://api.github.com/repos/' + SOURCE.owner + '/' + SOURCE.repo;
return [{
  json: {
    source: SOURCE,
    // latest commit that changed anything in the policy folder
    commits_url: api + '/commits?sha=' + encodeURIComponent(SOURCE.branch) + '&path=' + encodeURIComponent(SOURCE.path) + '&per_page=1',
    raw_base: 'https://raw.githubusercontent.com/' + SOURCE.owner + '/' + SOURCE.repo,
    path: SOURCE.path,
  },
}];

// ============================================================
// Policy_Docs_JS - turns the manifest into one item per policy document to download
// n8n Code node | Mode: "Run Once for All Items"
// Input : the manifest (policy-manifest.json) from "Policy_Manifest"
// Output: one item per document: { file, title, url, sha }
// ============================================================
const manifest = $input.first().json;
const src = $('Policy_Source_JS').first().json;
const sha = $('Policy_Commit').first().json.sha;
if (!sha) throw new Error("Policy_Commit returned no commit. Check the repository, branch and folder in 'Policy_Source_JS'.");
if (!Array.isArray(manifest.documents) || !manifest.documents.length) {
  throw new Error("policy-manifest.json has no 'documents' list.");
}
return manifest.documents.map((d) => {
  if (!d.file || !/\.pdf$/i.test(d.file)) throw new Error('Manifest document without a .pdf file name: ' + JSON.stringify(d));
  return { json: { file: d.file, title: d.title || d.file, sha, url: src.raw_base + '/' + sha + '/' + src.path + '/' + d.file } };
});
